const cust = await api.get("/customers");
const mails = await api.get("/mails");
const delayed = new Set(cust.items.filter(c => c.order && c.order.status === "delayed").map(c => c.id));
const complaintCust = new Set(mails.items.filter(m => m.label === "complaint" && m.customer_id).map(m => m.customer_id));
const result = [...delayed].filter(id => complaintCust.has(id));
return { customers: cust.count, mails: mails.count, delayedCount: delayed.size, result };
